const titles=['目的と読み手を決める','構成を試作する','読みやすさを確認する','気づきと改善点をまとめる'];
const actions=['誰に何を伝えたいか書き出す','見出しと画像の配置を試す','文字の大きさと余白を見比べる','試作を振り返り、次に直すことを記録する'];
let done=[true,true,false,false];
function render(){const n=done.filter(Boolean).length,i=done.indexOf(false);document.querySelector('#count').textContent=`${n} / 4項目`;document.querySelector('#percent').textContent=`${n*25}%`;document.querySelector('#progress').value=n;document.querySelector('#current').textContent=i<0?'全項目の確認が完了':titles[i];document.querySelector('#next').textContent=i<0?'次の学習目標へ。必要に応じて振り返りを追記する':actions[i];document.querySelector('#steps').innerHTML=titles.map((t,j)=>`<label class="step ${done[j]?'done':''}"><input type="checkbox" data-step="${j}" ${done[j]?'checked':''}><span><small>STEP ${j+1} · ${done[j]?'確認済み':j===i?'確認中':'未確認'}</small><strong>${t}</strong></span></label>`).join('');document.querySelectorAll('[data-step]').forEach(x=>x.onchange=()=>{done[Number(x.dataset.step)]=x.checked;render()});}document.querySelector('#reset').onclick=()=>{done=[true,true,false,false];document.querySelector('#memo').value='';render()};render();
